// Package typeshape holds the type-shape enumeration matrix: the
// generator-input-domain analog of the runtime's value-domain enumerations
// (../../DOMAINS.md). matrix_gen.go and oracle_gen.go are generated by gen.go
// (`go generate ./...`); this file is the hand-written harness that drives
// every generated cell against BOTH oracles.
//
// Comparison policy (stdlib-first, matching the README's divergence table):
//   - encoding/json is the primary semantic oracle: for every cell and value
//     state, zerojson's encoding must be byte-identical to encoding/json's,
//     UNLESS the cell is tagged with a documented divergence (map-key order),
//     in which case a semantic (decode-and-compare) match is required instead.
//   - easyjson is the migration oracle: zerojson's encoding must be
//     byte-identical to easyjson's too, except where a documented easyjson
//     divergence applies (promoted-field order; omitzero, which easyjson
//     ignores entirely — those cells carry no easyjson twin).
//   - decode round-trips through zerojson, and zerojson's output must
//     re-decode through encoding/json.
//
// The set of divergence reasons is closed and asserted (TestAllowlistClosed):
// any new relaxation must name one of the documented reasons, so the
// allowlist can never grow silently.
package typeshape

import (
	"bytes"
	"encoding/json"
	"github.com/neal/zerojson/conformance/internal/oracle"
	"reflect"
	"testing"
)

//go:generate go run gen.go

type matrixState struct {
	label string
	make  func() any // returns a fresh *T for this value state
}

type matrixCase struct {
	name        string
	states      []matrixState
	encZJ       func(any) ([]byte, error)
	decZJ       func([]byte) (any, error)
	encEJ       func(any) ([]byte, error) // nil if no easyjson twin
	stdSemantic bool
	stdReason   string
	ejSemantic  bool
	ejReason    string
}

// allowedReasons covers the wire-format differences exercised by this matrix,
// not every runtime divergence in the README. A cell may only relax a
// byte-identity comparison by naming one of these reasons.
var allowedReasons = map[string]bool{
	divMapOrder:   true,
	divEmbedOrder: true,
	divOmitzero:   true,
	divInvalidTag: true,
}

const (
	divMapOrder   = "map-key range order (vs stdlib's sorted keys): perf, semantically meaningless"
	divEmbedOrder = "promoted-field order (vs easyjson): stdlib/json-v2 position, not easyjson's after-direct-fields"
	divOmitzero   = "omitzero honored (vs easyjson, which ignores the option)"
	divInvalidTag = "invalid tag name falls back to the Go field name (vs easyjson, which emits the invalid tag verbatim)"
)

// jsonv2Drift lists the cells whose stdlib comparison is skipped under the
// v2-backed encoding/json Go 1.27 ships (detected by probing, see
// internal/oracle): classic v1 is the implementation the compatibility
// contract is written against, and these are the documented places where
// the v1-on-v2 layer itself moved. Every other cell must still match both
// implementations byte-for-byte.
var jsonv2Drift = map[string]string{
	"T_invalid_tagname": "v1-on-v2 truncates an invalid tag name (`a\\b`) at the backslash instead of falling back to the Go field name as classic v1 does; zerojson follows classic v1 (README compatibility contract)",
}

// semanticEqual reports whether two JSON encodings are semantically equal
// (order-insensitive for object keys), by unmarshaling both through
// encoding/json and deep-comparing.
func semanticEqual(a, b []byte) bool {
	var va, vb any
	if err := json.Unmarshal(a, &va); err != nil {
		return false
	}
	if err := json.Unmarshal(b, &vb); err != nil {
		return false
	}
	return reflect.DeepEqual(va, vb)
}

func TestTypeShapeMatrix(t *testing.T) {
	for _, c := range matrixCases {
		t.Run(c.name, func(t *testing.T) {
			for _, st := range c.states {
				t.Run(st.label, func(t *testing.T) {
					v := st.make()

					zj, err := c.encZJ(v)
					if err != nil {
						t.Fatalf("zerojson encode: %v", err)
					}
					std, err := json.Marshal(v)
					if err != nil {
						t.Fatalf("stdlib encode: %v", err)
					}

					// zerojson vs encoding/json (primary oracle).
					if reason, drifted := jsonv2Drift[c.name]; drifted && oracle.StdlibJSONV2 {
						t.Logf("stdlib comparison skipped: %s\n  zj:  %s\n  std: %s", reason, zj, std)
					} else if c.stdSemantic {
						if !semanticEqual(zj, std) {
							t.Fatalf("stdlib semantic mismatch (%s)\n  zj:  %s\n  std: %s", c.stdReason, zj, std)
						}
					} else if !bytes.Equal(zj, std) {
						t.Fatalf("stdlib byte mismatch\n  zj:  %s\n  std: %s", zj, std)
					}

					// zerojson output must re-decode through encoding/json.
					if err := json.Unmarshal(zj, reflect.New(reflect.TypeOf(v).Elem()).Interface()); err != nil {
						t.Fatalf("stdlib rejected zerojson output %q: %v", zj, err)
					}

					// zerojson vs easyjson (migration oracle).
					if c.encEJ != nil {
						ej, err := c.encEJ(v)
						if err != nil {
							t.Fatalf("easyjson encode: %v", err)
						}
						if c.ejSemantic {
							if !semanticEqual(zj, ej) {
								t.Fatalf("easyjson semantic mismatch (%s)\n  zj: %s\n  ej: %s", c.ejReason, zj, ej)
							}
						} else if !bytes.Equal(zj, ej) {
							t.Fatalf("easyjson byte mismatch\n  zj: %s\n  ej: %s", zj, ej)
						}
					}

					// Decode round-trip: zerojson decodes its own output, and
					// the re-encoding must be byte-identical to the first.
					dv, err := c.decZJ(zj)
					if err != nil {
						t.Fatalf("zerojson decode of own output %q: %v", zj, err)
					}
					rezj, err := c.encZJ(dv)
					if err != nil {
						t.Fatalf("zerojson re-encode: %v", err)
					}
					// Map cells re-encode in Go range order, so their
					// round-trip is only semantically stable (same as the
					// stdlib comparison policy); every other cell must be
					// byte-stable.
					if c.stdSemantic {
						if !semanticEqual(zj, rezj) {
							t.Fatalf("decode round-trip not semantically stable\n  first:  %s\n  second: %s", zj, rezj)
						}
					} else if !bytes.Equal(zj, rezj) {
						t.Fatalf("decode round-trip not stable\n  first:  %s\n  second: %s", zj, rezj)
					}
				})
			}
		})
	}
}

// TestTopLevelNull covers struct-root null: a top-level JSON null decodes to a
// no-op success (leaving the value zero), for every matrix struct shape —
// matching encoding/json's Unmarshal("null", &v). "nullx" must still error
// (the trailing-data check runs after null).
func TestTopLevelNull(t *testing.T) {
	for _, c := range matrixCases {
		t.Run(c.name, func(t *testing.T) {
			dv, err := c.decZJ([]byte("null"))
			if err != nil {
				t.Fatalf("decode top-level null: %v", err)
			}
			got, err := c.encZJ(dv)
			if err != nil {
				t.Fatal(err)
			}
			zero, err := c.encZJ(c.states[0].make()) // states[0] is always "zero"
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(got, zero) {
				t.Fatalf("null did not leave the value zero\n  null-decoded: %s\n  zero:         %s", got, zero)
			}
			if _, err := c.decZJ([]byte("nullx")); err == nil {
				t.Fatalf("trailing data after null was not rejected")
			}
		})
	}
}

// TestSetMapStrictness covers set-map strictness: a map[string]struct{}
// value must be an object (any contents, ignored) or null — a number,
// array, or string is rejected, matching encoding/json and easyjson.
func TestSetMapStrictness(t *testing.T) {
	accept := []string{`{"f":{"k":{}}}`, `{"f":{"k":{"x":1}}}`, `{"f":{"k":null}}`, `{"f":{"k":{"a":{"b":2}}}}`, `{"f":null}`}
	reject := []string{`{"f":{"k":123}}`, `{"f":{"k":[1]}}`, `{"f":{"k":"s"}}`, `{"f":{"k":true}}`}
	for _, in := range accept {
		var v C_map_set
		if err := v.UnmarshalZJSON([]byte(in)); err != nil {
			t.Errorf("accept %s: unexpected error %v", in, err)
		}
	}
	for _, in := range reject {
		var v C_map_set
		if err := v.UnmarshalZJSON([]byte(in)); err == nil {
			t.Errorf("reject %s: expected error, got none", in)
		}
	}
}

// TestAllowlistClosed asserts every relaxation names a documented reason —
// the allowlist cannot grow silently, and stays in sync with the README's
// divergence table.
func TestAllowlistClosed(t *testing.T) {
	for _, c := range matrixCases {
		if c.stdReason != "" && !allowedReasons[c.stdReason] {
			t.Errorf("%s: undocumented stdlib divergence reason %q", c.name, c.stdReason)
		}
		if c.ejReason != "" && !allowedReasons[c.ejReason] {
			t.Errorf("%s: undocumented easyjson divergence reason %q", c.name, c.ejReason)
		}
	}
}
